public class MutableDateTime_addWeeks_TriageGen2Test {











    @Test
    public void testAddWeeks_LeapYear() {
        // 2024 is a leap year. Feb 24, 2024 + 1 week = March 2, 2024
        MutableDateTime dt = new MutableDateTime(2024, 2, 24, 0, 0, 0, 0);
        dt.addWeeks(1);

        assertEquals(2024, dt.getYear());
        assertEquals(3, dt.getMonthOfYear());
        assertEquals(2, dt.getDayOfMonth());
    }
}
